<template><view class="page"><view class="card form"><picker :range="types" range-key="label" @change="typeIndex=Number($event.detail.value)"><view class="picker">申请类型：{{types[typeIndex].label}}</view></picker><picker v-if="type==='TRANSFER'" :range="targets" range-key="player_name" @change="targetIndex=Number($event.detail.value)"><view class="picker">转给：{{targets[targetIndex]?.player_name||'请选择接替陪玩'}}</view></picker><textarea v-model="reason" placeholder="请说明申请原因"/><button class="primary" @click="submit">提交平台审核</button></view></view></template>
<script setup lang="ts">import{computed,ref}from'vue';import{onLoad}from'@dcloudio/uni-app';import{createPlayerServiceException,getPlayerTransferTargets}from'@/api/player';import type{RecordData}from'@/types/api';const id=ref(0),targets=ref<RecordData[]>([]),targetIndex=ref(-1),typeIndex=ref(0),reason=ref('');const types=[{label:'申请转单',value:'TRANSFER'},{label:'申请炸单',value:'ABORT'}]as const;const type=computed(()=>types[typeIndex.value].value);onLoad(async q=>{id.value=Number(q?.id);targets.value=await getPlayerTransferTargets(id.value)});async function submit(){if(type.value==='TRANSFER'&&!targets.value[targetIndex.value])return uni.showToast({title:'请选择接替陪玩',icon:'none'});if(!reason.value.trim())return uni.showToast({title:'请填写申请原因',icon:'none'});await createPlayerServiceException(id.value,{requestType:type.value,targetPlayerId:type.value==='TRANSFER'?Number(targets.value[targetIndex.value].player_id):undefined,reason:reason.value});uni.showToast({title:'已提交审核'});setTimeout(()=>uni.navigateBack(),500)}</script>
<style scoped>.form{display:flex;flex-direction:column;gap:24rpx}.picker,.form textarea{padding:22rpx;border-radius:16rpx;background:#f5f6f2}.form textarea{width:100%;height:240rpx;box-sizing:border-box}</style>
